package br.com.atena.escolar.web;
import br.com.atena.escolar.infra.*;
import br.com.atena.escolar.domain.Resultado;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.core.Authentication;
import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
@RestController
public class BoletimController {
 final PessoaRepository people;final MatriculaRepository enrollments;final DisciplinaRepository disciplines;final TurmaRepository turmas;final MateriaRepository subjects;final NotaRepository grades;final AulaRepository lessons;final PresencaRepository attendance;final Access access;final String token;final UnidadeRepository units;
 public BoletimController(PessoaRepository p,MatriculaRepository e,DisciplinaRepository d,TurmaRepository t,MateriaRepository s,NotaRepository g,AulaRepository l,PresencaRepository a,UnidadeRepository units,Access access,@Value("${atena.service-token}") String token){people=p;enrollments=e;disciplines=d;turmas=t;subjects=s;grades=g;lessons=l;attendance=a;this.units=units;this.access=access;this.token=token;if(token.length()<32)throw new IllegalArgumentException("SERVICE_TOKEN deve ter pelo menos 32 caracteres");}
 @org.springframework.transaction.annotation.Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ) @GetMapping("/api/boletins/{alunoId}") public Map<String,Object> boletim(@PathVariable Long alunoId,Authentication auth){Pessoa user=access.person(auth);canReadStudent(alunoId,auth);return snapshot(alunoId,user.perfil.equals("PROFESSOR")?user.id:null,user.perfil.equals("ALUNO"));}
 public void canReadStudent(Long alunoId,Authentication auth){Pessoa p=access.person(auth);if(p.perfil.equals("ALUNO")&&!p.id.equals(alunoId))access.deny();if(p.perfil.equals("PROFESSOR")&&!enrollments.findByAlunoId(alunoId).stream().anyMatch(e->disciplines.findByTurmaId(e.turmaId).stream().anyMatch(d->p.id.equals(d.professorId))))access.deny();}
 @org.springframework.transaction.annotation.Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ) @GetMapping("/api/internal/snapshot/{alunoId}") public Map<String,Object> internal(@PathVariable Long alunoId,@RequestHeader(value="X-Service-Token",defaultValue="") String provided,@RequestParam(required=false)Long professorId,@RequestParam(defaultValue="false")boolean releasedOnly){if(!java.security.MessageDigest.isEqual(token.getBytes(java.nio.charset.StandardCharsets.UTF_8),provided.getBytes(java.nio.charset.StandardCharsets.UTF_8)))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Credencial de serviço inválida");return snapshot(alunoId,professorId,releasedOnly);}
 public Map<String,Object> snapshot(Long alunoId,Long professorId,boolean releasedOnly){Pessoa p=people.findById(alunoId).filter(x->x.perfil.equals("ALUNO")).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Aluno não encontrado"));List<Map<String,Object>> lines=new ArrayList<>();for(Matricula m:enrollments.findByAlunoId(alunoId)){Turma t=turmas.findById(m.turmaId).orElseThrow();for(Disciplina d:disciplines.findByTurmaId(m.turmaId)){if(professorId!=null&&!professorId.equals(d.professorId))continue;List<Nota> ns=grades.findByDisciplinaIdAndAlunoIdOrderByBimestre(d.id,alunoId);List<Double> values=new ArrayList<>(Arrays.asList(null,null,null,null));List<Double> recs=new ArrayList<>(Arrays.asList(null,null,null,null));for(Nota n:ns){if(!releasedOnly||n.liberada){values.set(n.bimestre-1,n.valor);recs.set(n.bimestre-1,n.recuperacao);}}int faltas=0;for(Aula l:lessons.findByDisciplinaId(d.id)){faltas+=attendance.findByAulaId(l.id).stream().filter(a->a.alunoId.equals(alunoId)).mapToInt(a->a.faltas).sum();}Map<String,Object> line=new LinkedHashMap<>();line.put("turma",t.nome);line.put("ano",t.ano);line.put("disciplina",subjects.findById(d.materiaId).orElseThrow().nome);line.put("disciplinaId",d.id);line.put("cargaHoraria",d.cargaHoraria);line.put("dependencia",m.dependencia);line.put("notas",values);line.put("recuperacoes",recs);line.put("faltas",faltas);line.put("resultado",Resultado.calcular(values,recs,faltas,d.cargaHoraria));lines.add(line);}}
 Unidade unit=units.findAll(org.springframework.data.domain.Sort.by("id")).stream().findFirst().orElse(null);
 Map<String,Object> school=unit==null?Map.of():Map.of("nome",unit.nome,"endereco",Objects.toString(unit.endereco,""),"telefone",Objects.toString(unit.telefone,""),"cnpj",Objects.toString(unit.cnpj,""));
 return Map.of("alunoId",p.id,"nome",p.nome,"matricula",p.matricula,"documento",professorId==null?Objects.toString(p.documento,""):"","unidade",school,"linhas",lines);
 }
}
